def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0.0
    eric_prev = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > strong_prev:
                    strong_prev = bid
                if agent_id == 'Eric':
                    eric_prev = bid

    if not alive:
        return min(budget, 18.0)

    competitor_count = len(alive) + 1
    scarcity = supply / float(WATER_REQ * competitor_count)

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    if scarcity < 0.45:
        base = 78.0
    elif scarcity < 0.6:
        base = 60.0
    elif scarcity < 0.8:
        base = 42.0
    else:
        base = 24.0

    if prev_bids:
        target_prev = strong_prev
        if eric_prev is not None and eric_prev >= 70.0:
            target_prev = eric_prev
        if urgent:
            bid = max(base, min(180.0, target_prev + 2.0))
        elif pressured:
            bid = max(base, min(120.0, target_prev * 0.72 + 3.0))
        else:
            if target_prev >= 100.0:
                bid = max(base, 26.0)
            elif target_prev >= 60.0:
                bid = max(base, target_prev * 0.52)
            else:
                bid = max(base, target_prev + 1.5)
    else:
        if urgent:
            bid = 75.0
        elif pressured:
            bid = 48.0
        else:
            bid = base

    if budget < 35.0:
        bid = min(bid, budget)
    elif budget < 80.0:
        bid = min(bid, budget * 0.92)
    else:
        bid = min(bid, budget * 0.68)

    if urgent and budget > 0:
        bid = max(bid, min(budget, 65.0))

    if hp >= 8 and no_water_days == 0 and scarcity > 0.75:
        bid = min(bid, 22.0)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Pull yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            bid = prev.get('bid', None)
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass
        elif isinstance(prev, list) and prev:
            # If previous_trace is list of events, only use the last entry (still immediate)
            last = prev[-1]
            if isinstance(last, dict):
                bid = last.get('bid', None)
                if bid is not None:
                    try:
                        prev_bids.append(float(bid))
                    except Exception:
                        pass

    # Estimate how hard others fought yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: with higher supply, winning doesn't need to be as expensive.
    # With lower supply, bid higher to secure enough water.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_frac = max(0.0, min(1.0, supply_frac))
    low_supply_factor = 1.15 - 0.15 * supply_frac  # 1.15 at min supply, 1.00 at max supply

    # Base target bid derived from observed surviving pressure.
    # Surviving agents bid around 100-120; we try to slightly exceed average or a fraction of highest.
    target = max(DAILY_SALARY * 0.45, avg_prev_bid * 1.02)

    # If someone bid very high yesterday, we match/overshoot to prevent being outbid.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, highest_prev_bid * 1.03)

    # If our HP is low or we've gone without water, increase aggressiveness.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        target *= 1.25
    elif my_hp <= 4.0:
        target *= 1.10

    # Apply supply factor
    target *= low_supply_factor

    # Final clamp: never exceed budget; also keep within reasonable bounds.
    # Budget might be small late-game; ensure non-negative.
    bid = max(0.0, min(my_budget, target))

    # Safety: if budget is tiny, still bid something to avoid zero-water streak.
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    strong_opponents_bids = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive'] and (opp_id == "Alex" or opp_id == "Eric"):
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                strong_opponents_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6 

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.8
    elif my_hp >= 8:
        base_bid = DAILY_SALARY * 0.5

    if strong_opponents_bids:
        max_yesterday_strong_bid = max(strong_opponents_bids)

        if max_yesterday_strong_bid >= DAILY_SALARY * 0.8:
            if my_hp <= 3:
                base_bid = max(base_bid, max_yesterday_strong_bid + 5)
            else:
                base_bid = max(base_bid, max_yesterday_strong_bid + 1)
        elif max_yesterday_strong_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, max_yesterday_strong_bid + 0.5)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_budget >= DAILY_SALARY * 1.5:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        elif my_hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.98)

    final_bid = max(1.0, min(my_budget, base_bid))

    return final_bid

